+    let parsed = super::parse_source(
+        r#"machine caller() {
+            select<match value { 0 -> 1, _ -> 2 }>();
+            select<(Record { value: 3 }).value + 1>();
+            select<[u8; 3]>();
+        }"#,
+        "grouped match arms, record fields and array extents stay inside static arguments",
